import { backendUrl } from "./config";

// Server-side client for the NestJS certificates API.

export type Certificate = {
  id: string;
  title: string;
  recipient: string;
  // SHA-256 of the certificate record, generated by the backend.
  contentHash: string;
  txHash: string | null;
  createdAt: string;
};

export type CreateCertificateInput = {
  title: string;
  recipient: string;
};

export class ApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${backendUrl}/api${path}`, {
    ...init,
    headers: { "Content-Type": "application/json", ...init?.headers },
  });
  const body: unknown = await res.json().catch(() => null);
  if (!res.ok) {
    throw new ApiError(res.status, errorMessage(body, res.status));
  }
  return body as T;
}

// NestJS errors carry `message` as a string or, for validation, a string[].
function errorMessage(body: unknown, status: number): string {
  const message = (body as { message?: unknown } | null)?.message;
  if (Array.isArray(message)) return message.join(". ");
  if (typeof message === "string") return message;
  return `Error ${status}`;
}

export function getCertificates(): Promise<Certificate[]> {
  return request("/certificates");
}

export function getCertificate(id: string): Promise<Certificate> {
  return request(`/certificates/${encodeURIComponent(id)}`);
}

export function createCertificate(
  input: CreateCertificateInput,
): Promise<Certificate> {
  return request("/certificates", {
    method: "POST",
    body: JSON.stringify(input),
  });
}

export function formatDate(iso: string): string {
  return new Intl.DateTimeFormat("es-AR", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(iso));
}
